text=' x '
def argument():
    print('argument')
    return ' '
try: text.strip(chars=argument())
except TypeError: print('keyword')
print(repr(text))

text=' x '
method=text.strip
for target in [method,str.strip.__get__(text,str)]:
    try: target(**{'chars':' '})
    except TypeError: print('keyword')
try: str.strip(text,chars=' ')
except TypeError: print('keyword')
print(method(),str.strip(text))

try: ' x '.strip(1)
except TypeError: print('type')
try: ' x '.strip(' ','x')
except TypeError: print('extra')
try: str.strip()
except TypeError: print('receiver')

class C:
    def __getattribute__(self,name):
        print('lookup',name)
        return lambda: 'ok'
print(C().strip())

class C: strip='not-callable'
try: C().strip()
except TypeError: print('not-callable')

class C:
    def strip(self,chars=None): return chars
print(C().strip(chars='x'))

class C:
    @property
    def strip(self):
        print('property')
        return lambda: 'ok'
print(C().strip())
